/* 万 / 亿 counts → K / M / B (for future rows matched by patterns) */
function lscWan(n) { n = +n * 1e4; return n >= 1e9 ? +(n / 1e9).toFixed(3) + "B" : n >= 1e6 ? +(n / 1e6).toFixed(2) + "M" : +(n / 1e3).toFixed(1) + "K"; }

I18N.patterns([
  /* UI with live numbers */
  [/^(.+) \| 买入:(\d+) 卖出:(\d+) 机构:(\d+)$/, function (m, c, b, s, i) {
    return I18N.tr(c) + " | buys: " + b + " · sells: " + s + " · institutions: " + i;
  }],
  [/^(\d+) 家机构$/, function (m, n) { return n + (n === "1" ? " institution" : " institutions"); }],

  /* timing_known */
  [/^披露日: ?(\d{4}-\d\d-\d\d)$/, function (m, d) { return "Filed: " + d; }],
  [/^(.+?)；披露日: ?(\d{4}-\d\d-\d\d)$/, function (m, a, d) { return I18N.tr(a) + "; filed " + d; }],
  [/^(.+?)；13G申报 ?(\d{4}-\d\d-\d\d)$/, function (m, a, d) { return I18N.tr(a) + "; 13G filed " + d; }],

  /* notes */
  [/^EDGAR 13F 自动生成/, "Auto-generated from EDGAR 13F, pending review"],
  [/^(.+?)；已按 EDGAR 校正$/, function (m, a) { return I18N.tr(a) + "; corrected per EDGAR"; }],
  [/^(新建仓|加仓|减仓|再减|卖出) ?([\d.]+)万股$/, function (m, a, n) {
    return { 新建仓: "New: ", 加仓: "Added ", 减仓: "Sold ", 再减: "Sold another ", 卖出: "Sold " }[a] + lscWan(n) + " shares";
  }],
  [/^(最大持仓|第二大持仓|第三大持仓|第四大持仓|第五大持仓|持仓) ?([\d.]+%)$/, function (m, a, p) {
    return I18N.tr(a) + ", " + p;
  }]
]);
